window.AUTH=window.AUTH||{};window.AUTH["90-913"]={"d":"90-913","id":"1991/90-913","n":"Board of Governors of the Federal Reserve System of the United States v. MCorp Financial, Inc.","src":["osg"],"briefs":[{"k":"respondent","label":"Brief for the Board of Governors of the Federal Reserve System of the United States of america","date":"","url":"https://www.justice.gov/osg/media/229636/dl?inline","side":"res","src":"osg","fmt":"Text","detail":"https://www.justice.gov/osg/brief/board-governors-federal-reserve-system-united-states-america-petitioner-v-mcorp-financia-0","toa":false,"n":74}],"opinion":"https://tile.loc.gov/storage-services/service/ll/usrep/usrep502/usrep502032/usrep502032.pdf","tr":false,"items":[{"t":"case","label":"Leedom v. Kyne","cite":"358 U.S. 184","y":1958,"id":"1958/14","sc":1,"op":4,"sum":"A Federal District Court had jurisdiction of an original suit to set aside the Board's determination because it was made in excess of the Board's powers. Pp. 184-191. 101 U. S. App. D. C. 398, 249 F. 2d 490, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Board of Governors v. First Lincolnwood Corp.","cite":"439 U.S. 234","y":1978,"id":"1978/77-832","sc":1,"sum":"Section 3 (a) of the Bank Holding Company Act of 1956 (Act) prohibits any company frdm acquiring control of a bank without prior approval by the Board of Governors of the Federal Reserve System (Board). Under § 3 (c) of the Act, the Board must disapprove a transaction that would, inter alia, generate anticompetitive effects not clearly outweighed by beneficial effects upon the acquired bank's ability to serve the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Manges v. Camp","cite":"474 F.2d 97","y":1973,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/474/97/","by":{"0":""}},{"t":"case","label":"Chevron U.S.A. Inc. v. Natural Resources Defense Council, Inc.","cite":"467 U.S. 837","y":1984,"id":"1983/82-1005","sc":1,"sum":"The Supreme Court held that the bubble regulation was a reasonable interpretation of the term “stationary source” in the Clean Air Act. Congress did not have a specific intention for the interpretation of that term, and the EPA’s regulation was a reasonable policy choice. The regulation also provided reasonable accommodations for the many competing interests affected by the Act.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Gulf Federal Savings & Loan Ass'n v. Federal Home Loan Bank Bd.","cite":"651 F.2d 259","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/651/259/","by":{"0":""}},{"t":"case","label":"Eastern Nat'l Bank v. Conover","cite":"786 F.2d 192","y":1986,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/786/192/","by":{"0":""}},{"t":"case","label":"Investment Co. Inst. v. FDIC","cite":"728 F.2d 518","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/728/518/","by":{"0":""}},{"t":"case","label":"First Nat'l Bank v. United States","cite":"530 F. Supp. 162","y":1982,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp./530/162/","by":{"0":""}},{"t":"case","label":"Groos Nat'l Bank v. Comptroller of Currency","cite":"573 F.2d 899","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/573/899/","by":{"0":""}},{"t":"case","label":"Business Guides, Inc. v. Chromatic Communications Enters., Inc.","cite":"111 S. Ct. 922","y":1991,"id":"1990/89-1500","sc":1,"sum":"Federal Rule of Civil Procedure 11 provides, in relevant part, that \"[t]he signature of an attorney or party constitutes a certificate by the sigfier that the signer has read the pleading, motion, or other paper\" and \"to the best of the signer's knowledge, information, and belief formed after reasonable inquiry it is well grounded in fact,\" and that a court shall impose an appropriate sanction \"upon the person who …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Pavelic & LeFlore v. Marvel Entertainment Group","cite":"110 S. Ct. 456","y":1989,"id":"1989/88-791","sc":1,"sum":"When read in the context of all of Rule ll's signature provisions, the phrase \"person who signed\" connotes the individual signer mentioned at the outset of the Rule and authorizes a court to impose a sanction only against that individual. That is so even when the individual explicitly signs on behalfof the firm, since it is only the signature \"in the attorney's individual name\" which complies with the Rule's …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Hallstrom v. Tillamook County","cite":"110 S. Ct. 304","y":1989,"id":"1989/88-42","sc":1,"sum":"Where a party suing under RCRA's citizen suit provision fails to meet the notice and 60-day delay requirements of § 6972(b), the action must be dismissed as barred by the terms of the statute.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Crawford Fitting Co. v. J.T. Gibbons, Inc.","cite":"482 U.S. 437","y":1987,"id":"1986/86-322","sc":1,"sum":"When a prevailing party seeks reimbursement for fees paid to its expert witnesses, a federal court is bound by the limits of § 1821(b), absent contract or explicit statutory authority to the contrary. There is no merit to petitioners' contentions that, since § 1920 lists expenses which a court \"may\" tax as costs, it only authorizes taxation of such items and does not preclude taxation for other items or amounts in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Colorado River Water Conservation Dist. v. United States","cite":"424 U.S. 800","y":1976,"id":"1975/74-940","sc":1,"sum":"In order to manage the allocation of water and to resolve conflicting claims thereto, Colorado enacted legislation under which the State is divided into seven Water Divisions, in each of which a procedure is established for the settlement of water claims on a continuous basis. A State Engineer is charged with responsibility for administering the distribution of state waters. Seeking adjudication of reserved rights …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Rosencrans v. United States","cite":"165 U.S. 257","y":1897,"id":"scdb/1896-085","sc":1,"sum":"Under the act of July'20, 1892, c. 208, the grand jury in the southern division, of the District of Montana had jurisdiction to And the indictment which forms the subject of discussion in this case; and, after such indictment had been found, the court had authority to remit it to the other. division for trial.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Chicago, B. & Q. Ry. v. Illinois ex rel. Drainage Commissioners","cite":"200 U.S. 561","y":1906,"id":"scdb/1905-091","sc":1,"sum":"The failure of the state court to pass on the Federal right or immunity specially set up of record, is not conclusive, but this court will decide the Federal question if the necessary effect of the judgment is to deny a Federal right or immunity specially set up or claimed, and which, if recognized and enforced, would require a judgment different from one resting upon some ground of local or general law.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Norwest Bank Worthington v. Ahlers","cite":"485 U.S. 197","y":1988,"id":"1987/86-958","sc":1,"sum":"The absolute priority rule applies, and respondents' promise of future labor warrants no exception to its operation.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Energy Resources Co.","cite":"110 S. Ct. 2139","y":1990,"id":"1989/89-255","sc":1,"sum":"A bankruptcy court has the authority to order the IRS to treat tax payments made by Chapter 11 debtor corporations as trust fund payments where the court determines that this designation is necessary for the success of a reorganization plan. Although the Bankruptcy Code does not explicitly authorize such a court to approve reorganization plans designating tax payments as either trust fund or nontrust fund, the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Midlantic Nat'l Bank v. New Jersey Dep't of Envt'l Protection","cite":"474 U.S. 494","y":1986,"id":"1985/84-801","sc":1,"sum":"A trustee in bankruptcy may not abandon property in contravention of a state statute or regulation that is reasonably designed to protect the public health or safety from identified hazards. Congress did not intend for §554(a) to pre-empt all state and local laws. A bankruptcy court does not have the power to authorize an abandonment without formulatResources Corp., Debtor v. City of New York et al., and O'Neill, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Swarts v. Hammer","cite":"194 U.S. 441","y":1904,"id":"scdb/1903-121","sc":1,"sum":"Where Congress has the power to exempt property from taxation the intention must be clearly expressed.","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Pennsylvania Dep't of Pub. Welfare v. Davenport","cite":"110 S. Ct. 2126","url":"https://www.courtlistener.com/c/S.%20Ct./110/2126/","sc":1,"by":{"0":""}},{"t":"case","label":"Brock v. Morysville Body Works, Inc.","cite":"829 F.2d 383","y":1987,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/829/383/","by":{"0":""}},{"t":"case","label":"Callaway v. Benton","cite":"336 U.S. 132","y":1949,"id":"scdb/1948-033","sc":1,"sum":"Under the narrow facts presented here, the bankruptcy court erred in enjoining the state court suit leading to a determination of the requirements of state law with respect to the sale of the entire assets of the lessor.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Grogan v. Garner","cite":"111 S. Ct. 654","y":1991,"id":"1990/89-1149","sc":1,"sum":"Courts should apply the \"preponderance of the evidence\" standard. Justice John Paul Stevens, for a unanimous Supreme Court, wrote that the lack of a specified standard of evidence in section 523(a) implied that Congress had intended the preponderance of the evidence standard to be used.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Morton v. Mancari","cite":"417 U.S. 535","y":1974,"id":"1973/73-362","sc":1,"sum":"In addition, the Court held that Section 472 did not constitute discrimination in violation of the Fifth Amendment. Again, Justice Blackmun cited the history of \"special treatment\" granted to Indians.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Boire v. Greyhound Corp.","cite":"376 U.S. 473","y":1964,"id":"1963/77","sc":1,"sum":"The NLRB's orders in certification proceedings under § 9 (c) of the Act are not final orders made reviewable by §§ 10 (e) and (f). Leedom v. Kyne, 358 U. S. 184, distinguished. They can, however, become reviewable where an employer's refusal to bargain with a certified unit results in an unfair labor act charge being brought, in which case § 9 (d) of the Act indirectly provides for full judicial review of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Brotherhood of Ry. & S.S. Clerks v. Association for the Benefit of Non-Contract Employees","cite":"380 U.S. 650","y":1965,"id":"1964/138","sc":1,"sum":"The Brotherhood of Railway and Steamship Clerks (Brotherhood) filed with the National Mediation Board (Board) an application under § 2, Ninth of the Railway Labor Act which as later amended requested investigation of a representation dispute among the \"clerical, office, stores, fleet and passenger service\" employees of United Air Lines (United). The Board had determined that grouping to be appropriate for collective …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Congress. E.g., Whitney Nat'l Bank v. Bank of New Orleans & Trust Co.","cite":"379 U.S. 411","y":1965,"id":"1964/26","sc":1,"sum":"A New Orleans-based national bank, desiring to expand but prohibited from operating branches beyond its home parish, formed a holding company which in turn organized a new national bank to operate in an adjoining parish. Pursuant to the Bank Holding Company Act of 1956, the Federal Reserve Board (FRB), after receiving favorable advice from the Comptroller of the Currency (Comptroller), held hearings on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"K Mart Corp. v. Cartier, Inc.","cite":"486 U.S. 281","y":1988,"id":"1987/86-495","sc":1,"sum":"The judgment is affirmed in part and reversed in part. 252 U. S. App. D. C. 342, 790 F. 2d 903, affirmed in part and reversed in part. JUSTICE KENNEDY delivered the opinion of the Court as to Parts I, II-A, and II-C, concluding that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Adams v. Nagle","cite":"303 U.S. 532","y":1938,"id":"scdb/1937-116","sc":1,"sum":"Stockholders of the \"P\" and \"R\" national banks brought bills in equity to enjoin the receiver from enforcing assessments, ordered by the Comptroller of the Currency pursuant to the statute governing the additional liability of shareholders, on the grounds that the action of the Comptroller in ordering the assessments was in excess of his statutory power, arbitrary, capricious, and a denial of due process of law. The …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Larson v. Domestic & Foreign Corp.","cite":"337 U.S. 682","y":1949,"id":"scdb/1948-106","sc":1,"sum":"The suit was one against the United States 4nd, in the absence of consent by the United States, the District Court was without jurisdiction. Pp. 684-705. 2.' In determining whether a suit nominally against an officer is against the officer individually or against the sovereign, the crucial qukestion is whether the relief sought is relief against the sovereign. Pp. 687-688. Statement of the Case.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"FTC v. Standard Oil Co.","cite":"449 U.S. 232","y":1980,"id":"1980/79-900","sc":1,"sum":"The FTC's issuance of its complaint was not \"final agency action\" under § 10 (c) of the APA and hence was not judicially reviewable before the conclusion of the administrative adjudication.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Lujan v. National Wildlife Federation","cite":"110 S. Ct. 3177","y":1990,"id":"1989/89-640","sc":1,"sum":"In a 5-to-4 decision written by Justice Antonin Scalia, the Supreme Court held that NWF did not have standing to challenge the land-use designations. The two timely affidavits were not enough to show that the group members had actually been affected by the BLM decisions.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Abbott Laboratories v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"op":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Leedom. Cf. Williamson Planning Comm'n v. Hamilton Bank","cite":"473 U.S. 172","y":1985,"id":"1984/84-4","sc":1,"sum":"The Supreme Court held that even if there was a temporary taking, a decision on money damages was premature because Hamilton Bank had not obtained a final administrative decision on the subdivision layout. The claim was premature under the Due Process Clause of the Fourteenth Amendment for the same reason. Justice Byron R. White dissented from the holding that the issues in the case were not ripe for decision.","sumSrc":"Oyez","by":{"0":""}},{"t":"case","label":"Investment Co. Inst. v. FDIC","cite":"815 F.2d 1540","url":"https://www.courtlistener.com/c/F.2d/815/1540/","by":{"0":""}},{"t":"case","label":"United States v. Philadelphia Nat'l Bank","cite":"374 U.S. 321","y":1963,"id":"1962/83","sc":1,"sum":"The proposed consolidation of appellee banks is forbidden by § 7 of the Clayton Act, and it must be enjoined.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Toilet Goods Ass'n v. Gardner","cite":"387 U.S. 158","y":1967,"id":"1966/336","sc":1,"sum":"Pre-enforcement judicial review of the regulation involved here is not appropriate as the controversy is not ripe for adjudication under the standards set forth in Abbott Laboratories v. Gardner, ante, p. 136.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"FPC v. Corporation Comm'n","cite":"362 F. Supp. 522","y":1973,"court":"W.D. Okla.","url":"https://www.courtlistener.com/c/F.%20Supp./362/522/","by":{"0":""}},{"t":"case","label":"Edleman v. Department of Labor","cite":"923 F.2d 782","y":1991,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/923/782/","by":{"0":""}},{"t":"case","label":"Brock v. Rusco Indus., Inc.","cite":"842 F.2d 270","url":"https://www.courtlistener.com/c/F.2d/842/270/","by":{"0":""}},{"t":"case","label":"NLRB v. Edward Cooper Painting, Inc.","cite":"804 F.2d 934","y":1986,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/804/934/","op":4,"by":{"0":""}},{"t":"case","label":"Cournoyer v. Town of Lincoln","cite":"790 F.2d 971","y":1986,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/790/971/","by":{"0":""}},{"t":"case","label":"CFTC v. Co Petro Marketing Group, Inc.","cite":"700 F.2d 1279","y":1983,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/700/1279/","by":{"0":""}},{"t":"case","label":"SEC v. First Financial Group","cite":"645 F.2d 429","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/645/429/","by":{"0":""}},{"t":"case","label":"Cline v. Kaplan","cite":"323 U.S. 97","y":1944,"id":"scdb/1944-013","sc":1,"sum":"1. Where a bona fide claim adverse to that of the bankrupt estate is asserted as to property which is not in the actual or constructive possession of the bankruptcy court, the claimant has the right to have the merits of his claim adjudicated in a plenary suit.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Thompson v. Magnolia Co.","cite":"309 U.S. 478","y":1940,"id":"scdb/1939-039","sc":1,"sum":"In a railroad reorganization proceeding under § 77 of the Bankruptcy Act in the federal court for Missouri, rights in oil underlying the right of way of the railroad in Illinois were claimed by the trustee and by others adversely. The trustee had possession of the right-of-way lands under claim of fee simple ownership.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":""}},{"t":"case","label":"Murphy v. John Hofman Co.","cite":"211 U.S. 562","y":1909,"id":"scdb/1908-051","sc":1,"sum":"Where the bankruptcy court has the actual possession of property, the title to which is in dispute, that property is withdrawn from the jurisdiction of other courts, and, independently of any jurisdiction conferred by statute, the bankruptcy court, as is the case with other Federal and state courts, has ancillary jurisdiction to hear and deteriáiiie all questions respecting such title; and such jurisdiction cannot …","sumSrc":"Headnote (U.S. Reports)","by":{"0":""}},{"t":"case","label":"United States v. Huckabee Auto Co.","cite":"783 F.2d 1546","y":1986,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/783/1546/","by":{"0":""}},{"t":"case","label":"Briggs Transp. Co. v. International Bhd. of Teamsters","cite":"739 F.2d 341","url":"https://www.courtlistener.com/c/F.2d/739/341/","by":{"0":""}},{"t":"case","label":"Telecommunications Research & Action Center v. FCC","cite":"750 F.2d 70","y":1984,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/750/70/","by":{"0":""}},{"t":"case","label":"Quivira Mining Co. v. EPA","cite":"728 F.2d 477","y":1984,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/728/477/","by":{"0":""}},{"t":"case","label":"Compensation Dep't v. Marshall","cite":"667 F.2d 336","y":1981,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/667/336/","by":{"0":""}},{"t":"case","label":"Nor-Am Agricultural Prods., Inc. v. Hardin","cite":"435 F.2d 1151","y":1970,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/435/1151/","by":{"0":""}},{"t":"case","label":"Greater Detroit Resource Recovery Auth. & Combustion Eng'g v. EPA","cite":"916 F.2d 317","y":1990,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/916/317/","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1842","url":"https://www.law.cornell.edu/uscode/text/12/1842","subs":["(a)"],"by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1818","url":"https://www.law.cornell.edu/uscode/text/12/1818","stext":{"head":"§1818. Termination of status as insured depository institution","paras":[[0,"(a) Termination of insurance"],[0,"(1) Voluntary termination"],[1,"Any insured depository institution which is not—"],[2,"(A) a national member bank;"],[2,"(B) a State member bank;"],[2,"(C) a Federal branch;"],[2,"(D) a Federal savings association; or"],[2,"(E) an insured branch which is required to be insured under subsection (a) or (b) 1 of section 3104 of this title,"],[1,"may terminate such depository institution's status as an insured depository institution if such insured institution provides written notice to the Corporation of the institution's intent to terminate such status not less than 90 days before the effective date of such termination."],[0,"(2) Involuntary termination"],[0,"(A) Notice to primary regulator"],[2,"If the Board of Directors determines that—"],[3,"(i) an insured depository institution or the directors or trustees of an insured depository institution have engaged or are engaging in unsafe or unsound practices in conducting the business of the depository institution;"],[3,"(ii) an insured depository institution is in an unsafe or unsound condition to continue operations as an insured institution; or"],[3,"(iii) an insured depository institution or the directors or trustees of the insured institution have violated any applicable law, regulation, order, condition imposed in writing by the Corporation in connection with the approval of any application or other request by the insured depository institution, or written agreement entered into between the insured depository institution and the Corporation,"],[2,"the Board of Directors shall notify the appropriate Federal banking agency with respect to such institution (if other than the Corporation) or the State banking supervisor of such institution (if the Corporation is the appropriate Federal banking agency) of the Board's determination and the facts and circumstances on which such determination is based for the purpose of securing the correction of such practice, condition, or violation. Such notice shall be given to the appropriate Federal banking agency not less than 30 days before the notice required by subparagraph (B), except that this period for notice to the appropriate Federal banking agency may be reduced or eliminated with the agreement of such agency."],[0,"(B) Notice of intention to terminate insurance"],[2,"If, after giving the notice required under subparagraph (A) with respect to an insured depository institution, the Board of Directors determines that any unsafe or unsound practice or condition or any violation specified in such notice requires the termination of the insured status of the insured depository institution, the Board shall—"],[3,"(i) serve written notice to the insured depository institution of the Board's intention to terminate the insured status of the institution;"],[3,"(ii) provide the insured depository institution with a statement of the charges on the basis of which the determination to terminate such institution's insured status was made (or a copy of the notice under subparagraph (A)); and"],[3,"(iii) notify the insured depository institution of the date (not less than 30 days after notice under this subparagraph) and place for a hearing before the Board of Directors (or any person designated by the Board) with respect to the termination of the institution's insured status."],[0,"(3) Hearing; termination"],[1,"If, on the basis of the evidence presented at a hearing before the Board of Directors (or any person designated by the Board for such purpose), in which all issues shall be determined on the record pursuant to section 554 of title 5 and the written findings of the Board of Directors (or such person) with respect to such evidence (which shall be conclusive), the Board of Directors finds that any unsafe or unsound practice or condition or any violation specified in the notice to an insured depository institution under paragraph (2)(B) or subsection (w) has been established, the Board of Directors may issue an order terminating the insured status of such depository institution effective as of a date subsequent to such finding."],[0,"(4) Appearance; consent to termination"],[1,"Unless the depository institution shall appear at the hearing by a duly authorized representative, it shall be deemed to have consented to the termination of its status as an insured depository institution and termination of such status thereupon may be ordered."],[0,"(5) Judicial review"],[1,"Any insured depository institution whose insured status has been terminated by order of the Board of Directors under this subsection shall have the right of judicial review of such order only to the same extent as provided for the review of orders under subsection (h) of this section."],[0,"(6) Publication of notice of termination"],[1,"The Corporation may publish notice of such termination and the depository institution shall give notice of such termination to each of its depositors at his last address of record on the books of the depository institution, in such manner and at such time as the Board of Directors may find to be necessary and may order for the protection of depositors."],[0,"(7) Temporary insurance of deposits insured as of termination"],[1,"After the termination of the insured status of any depository institution under the provisions of this subsection, the insured deposits of each depositor in the depository institution on the date of such termination, less all subsequent withdrawals from any deposits of such depositor, shall continue for a period of at least 6 months or up to 2 years, within the discretion of the Board of Directors, to be insured, and the depository institution shall continue to pay to the Corporation assessments as in the case of an insured depository institution during such period. No additions to any such deposits and no new deposits in such depository institution made after the date of such termination shall be insured by the Corporation, and the depository institution shall not advertise or hold itself out as having insured deposits unless in the same connection it shall also state with equal prominence that such additions to deposits and new deposits made after such date are not so insured. Such depository institution shall, in all other respects, be subject to the duties and obligations of an insured depository institution for the period referred to in the 1st sentence from the date of such termination, and in the event that such depository institution shall be closed on account of inability to meet the demands of its depositors within such period, the Corporation shall have the same powers and rights with respect to such depository institution as in case of an insured depository institution."],[0,"(8) Temporary suspension of insurance"],[0,"(A) In general"],[2,"If the Board of Directors initiates a termination proceeding under paragraph (2), and the Board of Directors, after consultation with the appropriate Federal banking agency, finds that an insured depository institution (other than a savings association to which subparagraph (B) applies) has no tangible capital under the capital guidelines or regulations of the appropriate Federal banking agency, the Corporation may issue a temporary order suspending deposit insurance on all deposits received by the institution."],[0,"(B) Special rule for certain savings institutions"],[0,"(i) Certain goodwill included in tangible capital"],[3,"In determining the tangible capital of a savings association for purposes of this paragraph, the Board of Directors shall include goodwill to the extent it is considered a component of capital under section 1464(t) of this title. Any savings association which would be subject to a suspension order under subparagraph (A) but for the operation of this subparagraph, shall be considered by the Corporation to be a \"special supervisory association\"."],[0,"(ii) Suspension order"],[3,"The Corporation may issue a temporary order suspending deposit insurance on all deposits received by a special supervisory association whenever the Board of Directors determines that—"],[4,"(I) the capital of such association, as computed utilizing applicable accounting standards, has suffered a material decline;"],[4,"(II) that such association (or its directors or officers) is engaging in an unsafe or unsound practice in conducting the business of the association;"],[4,"(III) that such association is in an unsafe or unsound condition to continue operating as an insured association; or"],[4,"(IV) that such association (or its directors or officers) has violated any applicable law, rule, regulation, or order, or any condition imposed in writing by a Federal banking agency, or any written agreement including a capital improvement plan entered into with any Federal banking agency, or that the association has failed to enter into a capital improvement plan which is acceptable to the Corporation within the time period set forth in section 1464(t) of this title."],[0,"Nothing in this paragraph limits the right of the Corporation or the Comptroller of the Currency to enforce a contractual provision which authorizes the Corporation or the Comptroller of the Currency, as a successor to the Federal Savings and Loan Insurance Corporation or the Federal Home Loan Bank Board, to require a savings association to write down or amortize goodwill at a faster rate than otherwise required under this chapter or under applicable accounting standards."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1818?type=usc&year=mostrecent&link-type=html"},"op":6,"head":"§1818. Termination of status as insured depository institution","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 3907","url":"https://www.law.cornell.edu/uscode/text/12/3907","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 371c","url":"https://www.law.cornell.edu/uscode/text/12/371c","stext":{"head":"§371c. Banking affiliates","paras":[[0,"(a) Restrictions on transactions with affiliates"],[0,"(1) A member bank and its subsidiaries may engage in a covered transaction with an affiliate only if—"],[1,"(A) in the case of any affiliate, the aggregate amount of covered transactions of the member bank and its subsidiaries will not exceed 10 per centum of the capital stock and surplus of the member bank; and"],[1,"(B) in the case of all affiliates, the aggregate amount of covered transactions of the member bank and its subsidiaries will not exceed 20 per centum of the capital stock and surplus of the member bank."],[0,"(2) For the purpose of this section, any transaction by a member bank with any person shall be deemed to be a transaction with an affiliate to the extent that the proceeds of the transaction are used for the benefit of, or transferred to, that affiliate."],[0,"(3) A member bank and its subsidiaries may not purchase a low-quality asset from an affiliate unless the bank or such subsidiary, pursuant to an independent credit evaluation, committed itself to purchase such asset prior to the time such asset was acquired by the affiliate."],[0,"(4) Any covered transactions and any transactions exempt under subsection (d) between a member bank and an affiliate shall be on terms and conditions that are consistent with safe and sound banking practices."],[0,"(b) Definitions"],[0,"For the purpose of this section—"],[1,"(1) the term \"affiliate\" with respect to a member bank means—"],[2,"(A) any company that controls the member bank and any other company that is controlled by the company that controls the member bank;"],[2,"(B) a bank subsidiary of the member bank;"],[2,"(C) any company—"],[3,"(i) that is controlled directly or indirectly, by a trust or otherwise, by or for the benefit of shareholders who beneficially or otherwise control, directly or indirectly, by trust or otherwise, the member bank or any company that controls the member bank; or"],[3,"(ii) in which a majority of its directors or trustees constitute a majority of the persons holding any such office with the member bank or any company that controls the member bank;"],[2,"(D) any investment fund with respect to which a member bank or affiliate thereof is an investment adviser; and"],[2,"(E) any company that the Board determines by regulation or order to have a relationship with the member bank or any subsidiary or affiliate of the member bank, such that covered transactions by the member bank or its subsidiary with that company may be affected by the relationship to the detriment of the member bank or its subsidiary; and"],[1,"(2) the following shall not be considered to be an affiliate:"],[2,"(A) any company, other than a bank, that is a subsidiary of a member bank, unless a determination is made under paragraph (1)(E) not to exclude such subsidiary company from the definition of affiliate;"],[2,"(B) any company engaged solely in holding the premises of the member bank;"],[2,"(C) any company engaged solely in conducting a safe deposit business;"],[2,"(D) any company engaged solely in holding obligations of the United States or its agencies or obligations fully guaranteed by the United States or its agencies as to principal and interest; and"],[2,"(E) any company where control results from the exercise of rights arising out of a bona fide debt previously contracted, but only for the period of time specifically authorized under applicable State or Federal law or regulation or, in the absence of such law or regulation, for a period of two years from the date of the exercise of such rights or the effective date of this Act, whichever date is later, subject, upon application, to authorization by the Board for good cause shown of extensions of time for not more than one year at a time, but such extensions in the aggregate shall not exceed three years;"],[1,"(3)(A) a company or shareholder shall be deemed to have control over another company if—"],[2,"(i) such company or shareholder, directly or indirectly, or acting through one or more other persons owns, controls, or has power to vote 25 per centum or more of any class of voting securities of the other company;"],[2,"(ii) such company or shareholder controls in any manner the election of a majority of the directors or trustees of the other company; or"],[2,"(iii) the Board determines, after notice and opportunity for hearing, that such company or shareholder, directly or indirectly, exercises a controlling influence over the management or policies of the other company; and"],[1,"(B) notwithstanding any other provision of this section, no company shall be deemed to own or control another company by virtue of its ownership or control of shares in a fiduciary capacity, except as provided in paragraph (1)(C) of this subsection or if the company owning or controlling such shares is a business trust;"],[1,"(4) the term \"subsidiary\" with respect to a specified company means a company that is controlled by such specified company;"],[1,"(5) the term \"bank\" includes a State bank, national bank, banking association, and trust company;"],[1,"(6) the term \"company\" means a corporation, partnership, business trust, association, or similar organization and, unless specifically excluded, the term \"company\" includes a \"member bank\" and a \"bank\";"],[1,"(7) the term \"covered transaction\" means with respect to an affiliate of a member bank—"],[2,"(A) a loan or extension of credit to the affiliate, including a purchase of assets subject to an agreement to repurchase;"],[2,"(B) a purchase of or an investment in securities issued by the affiliate;"],[2,"(C) a purchase of assets from the affiliate, except such purchase of real and personal property as may be specifically exempted by the Board by order or regulation;"],[2,"(D) the acceptance of securities or other debt obligations issued by the affiliate as collateral security for a loan or extension of credit to any person or company;"],[2,"(E) the issuance of a guarantee, acceptance, or letter of credit, including an endorsement or standby letter of credit, on behalf of an affiliate;"],[2,"(F) a transaction with an affiliate that involves the borrowing or lending of securities, to the extent that the transaction causes a member bank or a subsidiary to have credit exposure to the affiliate; or"],[2,"(G) a derivative transaction, as defined in paragraph (3) of section 84(b) of this title, with an affiliate, to the extent that the transaction causes a member bank or a subsidiary to have credit exposure to the affiliate;"],[1,"(8) the term \"aggregate amount of covered transactions\" means the amount of the covered transactions about to be engaged in added to the current amount of all outstanding covered transactions;"],[1,"(9) the term \"securities\" means stocks, bonds, debentures, notes, or other similar obligations; and"],[1,"(10) the term \"low-quality asset\" means an asset that falls in any one or more of the following categories:"],[2,"(A) an asset classified as \"substandard\", \"doubtful\", or \"loss\" or treated as \"other loans especially mentioned\" in the most recent report of examination or inspection of an affiliate prepared by either a Federal or State supervisory agency;"],[2,"(B) an asset in a nonaccrual status;"],[2,"(C) an asset on which principal or interest payments are more than thirty days past due; or"],[2,"(D) an asset whose terms have been renegotiated or compromised due to the deteriorating financial condition of the obligor."],[1,"(11) Rebuttable presumption of control of portfolio companies.—In addition to paragraph (3), a company or shareholder shall be presumed to control any other company if the company or shareholder, directly or indirectly, or acting through 1 or more other persons, owns or controls 15 percent or more of the equity capital of the other company pursuant to subparagraph (H) or (I) of section 1843(k)(4) of this title or rules adopted under section 122 of the Gramm-Leach-Bliley Act, if any, unless the company or shareholder provides information acceptable to the Board to rebut this presumption of control."],[0,"(c) Collateral for certain transactions with affiliates"],[0,"(1) Each loan or extension of credit to, or guarantee, acceptance, or letter of credit issued on behalf of, an affiliate by a member bank or its subsidiary, and any credit exposure of a member bank or a subsidiary to an affiliate resulting from a securities borrowing or lending transaction, or a derivative transaction, shall be secured at all times by collateral having a market value equal to—"],[1,"(A) 100 per centum of the amount of such loan or extension of credit, guarantee, acceptance, letter of credit, or credit exposure, if the collateral is composed of—"],[2,"(i) obligations of the United States or its agencies;"],[2,"(ii) obligations fully guaranteed by the United States or its agencies as to principal and interest;"],[2,"(iii) notes, drafts, bills of exchange or bankers' acceptances that are eligible for rediscount or purchase by a Federal Reserve Bank; or"],[2,"(iv) a segregated, earmarked deposit account with the member bank;"],[1,"(B) 110 per centum of the amount of such loan or extension of credit, guarantee, acceptance, letter of credit, or credit exposure if the collateral is composed of obligations of any State or political subdivision of any State;"],[1,"(C) 120 per centum of the amount of such loan or extension of credit, guarantee, acceptance, letter of credit, or credit exposure if the collateral is composed of other debt instruments, including receivables; or"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/371c?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§371c. Banking affiliates","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"11 U.S.C. § 105","url":"https://www.law.cornell.edu/uscode/text/11/105","by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 1334","url":"https://www.law.cornell.edu/uscode/text/28/1334","subs":["(b)"],"stext":{"head":"§1334. Bankruptcy cases and proceedings","paras":[[0,"(a) Except as provided in subsection (b) of this section, the district courts shall have original and exclusive jurisdiction of all cases under title 11."],[0,"(b) Except as provided in subsection (e)(2), and notwithstanding any Act of Congress that confers exclusive jurisdiction on a court or courts other than the district courts, the district courts shall have original but not exclusive jurisdiction of all civil proceedings arising under title 11, or arising in or related to cases under title 11."],[0,"(c)(1) Except with respect to a case under chapter 15 of title 11, nothing in this section prevents a district court in the interest of justice, or in the interest of comity with State courts or respect for State law, from abstaining from hearing a particular proceeding arising under title 11 or arising in or related to a case under title 11."],[0,"(2) Upon timely motion of a party in a proceeding based upon a State law claim or State law cause of action, related to a case under title 11 but not arising under title 11 or arising in a case under title 11, with respect to which an action could not have been commenced in a court of the United States absent jurisdiction under this section, the district court shall abstain from hearing such proceeding if an action is commenced, and can be timely adjudicated, in a State forum of appropriate jurisdiction."],[0,"(d) Any decision to abstain or not to abstain made under subsection (c) (other than a decision not to abstain in a proceeding described in subsection (c)(2)) is not reviewable by appeal or otherwise by the court of appeals under section 158(d), 1291, or 1292 of this title or by the Supreme Court of the United States under section 1254 of this title. Subsection (c) and this subsection shall not be construed to limit the applicability of the stay provided for by section 362 of title 11, United States Code, as such section applies to an action affecting the property of the estate in bankruptcy."],[0,"(e) The district court in which a case under title 11 is commenced or is pending shall have exclusive jurisdiction—"],[1,"(1) of all the property, wherever located, of the debtor as of the commencement of such case, and of property of the estate; and"],[1,"(2) over all claims or causes of action that involve construction of section 327 of title 11, United States Code, or rules relating to disclosure requirements under section 327."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1334?type=usc&year=mostrecent&link-type=html"},"op":5,"head":"§1334. Bankruptcy cases and proceedings","tname":"Judiciary and Judicial Procedure","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1841","url":"https://www.law.cornell.edu/uscode/text/12/1841","subs":["(a)(1)"],"stext":{"head":"§1841. Definitions","paras":[[0,"(a)(1) Except as provided in paragraph (5) of this subsection, \"bank holding company\" means any company which has control over any bank or over any company that is or becomes a bank holding company by virtue of this chapter."],[0,"(2) Any company has control over a bank or over any company if—"],[1,"(A) the company directly or indirectly or acting through one or more other persons owns, controls, or has power to vote 25 per centum or more of any class of voting securities of the bank or company;"],[1,"(B) the company controls in any manner the election of a majority of the directors or trustees of the bank or company; or"],[1,"(C) the Board determines, after notice and opportunity for hearing, that the company directly or indirectly exercises a controlling influence over the management or policies of the bank or company."],[0,"(3) For the purposes of any proceeding under paragraph (2)(C) of this subsection, there is a presumption that any company which directly or indirectly owns, controls, or has power to vote less than 5 per centum of any class of voting securities of a given bank or company does not have control over that bank or company."],[0,"(4) In any administrative or judicial proceeding under this chapter, other than a proceeding under paragraph (2)(C) of this subsection, a company may not be held to have had control over any given bank or company at any given time unless that company, at the time in question, directly or indirectly owned, controlled, or had power to vote 5 per centum or more of any class of voting securities of the bank or company, or had already been found to have control in a proceeding under paragraph (2)(C)."],[0,"(5) Notwithstanding any other provision of this subsection—"],[1,"(A) No bank and no company owning or controlling voting shares of a bank is a bank holding company by virtue of its ownership or control of shares in a fiduciary capacity, except as provided in paragraphs (2) and (3) of subsection (g) of this section. For the purpose of the preceding sentence, bank shares shall not be deemed to have been acquired in a fiduciary capacity if the acquiring bank or company has sole discretionary authority to exercise voting rights with respect thereto; except that this limitation is applicable in the case of a bank or company acquiring such shares prior to December 31, 1970, only if the bank or company has the right consistent with its obligations under the instrument, agreement, or other arrangement establishing the fiduciary relationship to divest itself of such voting rights and fails to exercise that right to divest within a reasonable period not to exceed one year after December 31, 1970."],[1,"(B) No company is a bank holding company by virtue of its ownership or control of shares acquired by it in connection with its underwriting of securities if such shares are held only for such period of time as will permit the sale thereof on a reasonable basis."],[1,"(C) No company formed for the sole purpose of participating in a proxy solicitation is a bank holding company by virtue of its control of voting rights of shares acquired in the course of such solicitation."],[1,"(D) No company is a bank holding company by virtue of its ownership or control of shares acquired in securing or collecting a debt previously contracted in good faith, until two years after the date of acquisition. The Board is authorized upon application by a company to extend, from time to time for not more than one year at a time, the two-year period referred to herein for disposing of any shares acquired by a company in the regular course of securing or collecting a debt previously contracted in good faith, if, in the Board's judgment, such an extension would not be detrimental to the public interest, but no such extension shall in the aggregate exceed three years."],[1,"(E) No company is a bank holding company by virtue of its ownership or control of any State-chartered bank or trust company which—"],[2,"(i) is wholly owned by 1 or more thrift institutions or savings banks; and"],[2,"(ii) is restricted to accepting—"],[3,"(I) deposits from thrift institutions or savings banks;"],[3,"(II) deposits arising out of the corporate business of the thrift institutions or savings banks that own the bank or trust company; or"],[3,"(III) deposits of public moneys."],[1,"(F) No trust company or mutual savings bank which is an insured bank under the Federal Deposit Insurance Act [12 U.S.C. 1811 et seq.] is a bank holding company by virtue of its direct or indirect ownership or control of one bank located in the same State, if (i) such ownership or control existed on December 31, 1970, and is specifically authorized by applicable State law, and (ii) the trust company or mutual savings bank does not after that date acquire an interest in any company that, together with any other interest it holds in that company, will exceed 5 per centum of any class of the voting shares of that company, except that this limitation shall not be applicable to investments of the trust company or mutual savings bank, direct and indirect, which are otherwise in accordance with the limitations applicable to national banks under section 24 of this title."],[0,"(6) For the purposes of this chapter, any successor to a bank holding company shall be deemed to be a bank holding company from the date on which the predecessor company became a bank holding company."],[0,"(b) \"Company\" means any corporation, partnership, business trust, association, or similar organization, or any other trust unless by its terms it must terminate within twenty-five years or not later than twenty-one years and ten months after the death of individuals living on the effective date of the trust but shall not include any corporation the majority of the shares of which are owned by the United States or by any State, and shall not include a qualified family partnership. \"Company covered in 1970\" means a company which becomes a bank holding company as a result of the enactment of the Bank Holding Company Act Amendments of 1970 and which would have been a bank holding company on June 30, 1968, if those amendments had been enacted on that date."],[0,"(c) Bank Defined.—For purposes of this chapter—"],[1,"(1) In general.—Except as provided in paragraph (2), the term \"bank\" means any of the following:"],[2,"(A) An insured bank as defined in section 3(h) of the Federal Deposit Insurance Act [12 U.S.C. 1813(h)]."],[2,"(B) An institution organized under the laws of the United States, any State of the United States, the District of Columbia, any territory of the United States, Puerto Rico, Guam, American Samoa, or the Virgin Islands which both—"],[3,"(i) accepts demand deposits or deposits that the depositor may withdraw by check or similar means for payment to third parties or others; and"],[3,"(ii) is engaged in the business of making commercial loans."],[1,"(2) Exceptions.—The term \"bank\" does not include any of the following:"],[2,"(A) A foreign bank which would be a bank within the meaning of paragraph (1) solely because such bank has an insured or uninsured branch in the United States."],[2,"(B) An insured institution (as defined in subsection (j))."],[2,"(C) An organization that does not do business in the United States except as an incident to its activities outside the United States."],[2,"(D) An institution that functions solely in a trust or fiduciary capacity, if—"],[3,"(i) all or substantially all of the deposits of such institution are in trust funds and are received in a bona fide fiduciary capacity;"],[3,"(ii) no deposits of such institution which are insured by the Federal Deposit Insurance Corporation are offered or marketed by or through an affiliate of such institution;"],[3,"(iii) such institution does not accept demand deposits or deposits that the depositor may withdraw by check or similar means for payment to third parties or others or make commercial loans; and"],[3,"(iv) such institution does not—"],[4,"(I) obtain payment or payment related services from any Federal Reserve bank, including any service referred to in section 11A of the Federal Reserve Act [12 U.S.C. 248a]; or"],[4,"(II) exercise discount or borrowing privileges pursuant to section 19(b)(7) of the Federal Reserve Act [12 U.S.C. 461(b)(7)]."],[2,"(E) A credit union (as described in section 19(b)(1)(A)(iv) of the Federal Reserve Act [12 U.S.C. 461(b)(1)(A)(iv)])."],[2,"(F) An institution, including an institution that accepts collateral for extensions of credit by holding deposits under $100,000, and by other means which—"],[3,"(i) engages only in credit card operations;"],[3,"(ii) does not accept demand deposits or deposits that the depositor may withdraw by check or similar means for payment to third parties or others;"],[3,"(iii) does not accept any savings or time deposit of less than $100,000;"],[3,"(iv) maintains only one office that accepts deposits; and"],[3,"(v) does not engage in the business of making commercial loans, other than credit card loans that are made to businesses that meet the criteria for a small business concern to be eligible for business loans under regulations established by the Small Business Administration under part 121 of title 13, Code of Federal Regulations."],[2,"(G) An organization operating under section 25 or section 25(a) 1 of the Federal Reserve Act."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1841?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1841. Definitions","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 3901","url":"https://www.law.cornell.edu/uscode/text/12/3901","stext":{"head":"§3901. Congressional declaration of policy","paras":[[0,"(a)(1) It is the policy of the Congress to assure that the economic health and stability of the United States and the other nations of the world shall not be adversely affected or threatened in the future by imprudent lending practices or inadequate supervision."],[0,"(2) This shall be achieved by strengthening the bank regulatory framework to encourage prudent private decisionmaking and by enhancing international coordination among bank regulatory authorities."],[0,"(b) The Federal banking agencies shall consult with the banking supervisory authorities of other countries to reach understandings aimed at achieving the adoption of effective and consistent supervisory policies and practices with respect to international lending."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/3901?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§3901. Congressional declaration of policy","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1843","url":"https://www.law.cornell.edu/uscode/text/12/1843","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1844","url":"https://www.law.cornell.edu/uscode/text/12/1844","subs":["(c)"],"stext":{"head":"§1844. Administration","paras":[[0,"(a) Registration of bank holding company"],[0,"Within one hundred and eighty days after May 9, 1956, or within one hundred and eighty days after becoming a bank holding company, whichever is later, each bank holding company shall register with the Board on forms prescribed by the Board, which shall include such information with respect to the financial condition and operations, management, and intercompany relationships of the bank holding company and its subsidiaries, and related matters, as the Board may deem necessary or appropriate to carry out the purposes of this chapter. The Board may, in its discretion, extend the time within which a bank holding company shall register and file the requisite information. A declaration filed in accordance with section 1843(l)(1)(C) 1 of this title shall satisfy the requirements of this subsection with regard to the registration of a bank holding company but not any requirement to file an application to acquire a bank pursuant to section 1842 of this title."],[0,"(b) Regulations and orders"],[0,"The Board is authorized to issue such regulations and orders, including regulations and orders relating to the capital requirements for bank holding companies, as may be necessary to enable it to administer and carry out the purposes of this chapter and prevent evasions thereof. In establishing capital regulations pursuant to this subsection, the Board shall seek to make such requirements countercyclical, so that the amount of capital required to be maintained by a company increases in times of economic expansion and decreases in times of economic contraction, consistent with the safety and soundness of the company."],[0,"(c) Reports and examinations"],[0,"(1) Reports"],[0,"(A) In general"],[2,"The Board, from time to time, may require a bank holding company and any subsidiary of such company to submit reports under oath to keep the Board informed as to—"],[3,"(i) its financial condition, systems for monitoring and controlling financial and operating risks, and transactions with depository institution subsidiaries of the bank holding company; and"],[3,"(ii) compliance by the bank holding company or subsidiary with—"],[4,"(I) this chapter;"],[4,"(II) Federal laws that the Board has specific jurisdiction to enforce against the company or subsidiary; and"],[4,"(III) other than in the case of an insured depository institution or functionally regulated subsidiary, any other applicable provision of Federal law."],[0,"(B) Use of existing reports and other supervisory information"],[2,"The Board shall, to the fullest extent possible, use—"],[3,"(i) reports and other supervisory information that the bank holding company or any subsidiary thereof has been required to provide to other Federal or State regulatory agencies;"],[3,"(ii) externally audited financial statements of the bank holding company or subsidiary;"],[3,"(iii) information otherwise available from Federal or State regulatory agencies; and"],[3,"(iv) information that is otherwise required to be reported publicly."],[0,"(C) Availability"],[2,"Upon the request of the Board, the bank holding company or a subsidiary of the bank holding company shall promptly provide to the Board any information described in clauses (i) through (iii) of subparagraph (B)."],[0,"(2) Examinations"],[0,"(A) In general"],[2,"Subject to subtitle B of the Consumer Financial Protection Act of 2010 [12 U.S.C. 5511 et seq.], the Board may make examinations of a bank holding company and each subsidiary of a bank holding company in order to—"],[3,"(i) inform the Board of—"],[4,"(I) the nature of the operations and financial condition of the bank holding company and the subsidiary;"],[4,"(II) the financial, operational, and other risks within the bank holding company system that may pose a threat to—"],[5,"(aa) the safety and soundness of the bank holding company or of any depository institution subsidiary of the bank holding company; or"],[5,"(bb) the stability of the financial system of the United States; and"],[4,"(III) the systems of the bank holding company for monitoring and controlling the risks described in subclause (II); and"],[3,"(ii) monitor the compliance of the bank holding company and the subsidiary with—"],[4,"(I) this chapter;"],[4,"(II) Federal laws that the Board has specific jurisdiction to enforce against the company or subsidiary; and"],[4,"(III) other than in the case of an insured depository institution or functionally regulated subsidiary, any other applicable provisions of Federal law."],[0,"(B) Use of reports to reduce examinations"],[2,"For purposes of this paragraph, the Board shall, to the fullest extent possible, rely on—"],[3,"(i) examination reports made by other Federal or State regulatory agencies relating to a bank holding company and any subsidiary of a bank holding company; and"],[3,"(ii) the reports and other information required under paragraph (1)."],[0,"(C) Coordination with other regulators"],[2,"The Board shall—"],[3,"(i) provide reasonable notice to, and consult with, the appropriate Federal banking agency, the Securities and Exchange Commission, the Commodity Futures Trading Commission, or State regulatory agency, as appropriate, for a subsidiary that is a depository institution or a functionally regulated subsidiary of a bank holding company before commencing an examination of the subsidiary under this section; and"],[3,"(ii) to the fullest extent possible, avoid duplication of examination activities, reporting requirements, and requests for information."],[0,"(3) Capital"],[0,"(A) In general"],[2,"The Board may not, by regulation, guideline, order, or otherwise, prescribe or impose any capital or capital adequacy rules, guidelines, standards, or requirements on any functionally regulated subsidiary of a bank holding company that—"],[3,"(i) is not a depository institution; and"],[3,"(ii) is—"],[4,"(I) in compliance with the applicable capital requirements of its Federal regulatory authority (including the Securities and Exchange Commission) or State insurance authority;"],[4,"(II) properly registered as an investment adviser under the Investment Advisers Act of 1940 [15 U.S.C. 80b–1 et seq.], or with any State; or"],[4,"(III) is licensed as an insurance agent with the appropriate State insurance authority."],[0,"(B) Rule of construction"],[2,"Subparagraph (A) shall not be construed as preventing the Board from imposing capital or capital adequacy rules, guidelines, standards, or requirements with respect to—"],[3,"(i) activities of a registered investment adviser other than with respect to investment advisory activities or activities incidental to investment advisory activities; or"],[3,"(ii) activities of a licensed insurance agent other than insurance agency activities or activities incidental to insurance agency activities."],[0,"(C) Limitations on indirect action"],[2,"In developing, establishing, or assessing bank holding company capital or capital adequacy rules, guidelines, standards, or requirements for purposes of this paragraph, the Board may not take into account the activities, operations, or investments of an affiliated investment company registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.], unless the investment company is—"],[3,"(i) a bank holding company; or"],[3,"(ii) controlled by a bank holding company by reason of ownership by the bank holding company (including through all of its affiliates) of 25 percent or more of the shares of the investment company, and the shares owned by the bank holding company have a market value equal to more than $1,000,000."],[0,"(4) Functional regulation of securities and insurance activities"],[0,"(A) Securities activities"],[2,"Securities activities conducted in a functionally regulated subsidiary of a depository institution shall be subject to regulation by the Securities and Exchange Commission, and by relevant State securities authorities, as appropriate, subject to section 6701 of title 15, to the same extent as if they were conducted in a nondepository institution subsidiary of a bank holding company."],[0,"(B) Insurance activities"],[2,"Subject to section 6701 of title 15, insurance agency and brokerage activities and activities as principal conducted in a functionally regulated subsidiary of a depository institution shall be subject to regulation by a State insurance authority to the same extent as if they were conducted in a nondepository institution subsidiary of a bank holding company."],[0,"(5) Definition"],[1,"For purposes of this subsection, the term \"functionally regulated subsidiary\" means any company—"],[2,"(A) that is not a bank holding company or a depository institution; and"],[2,"(B) that is—"],[3,"(i) a broker or dealer that is registered under the Securities Exchange Act of 1934 [15 U.S.C. 78a et seq.];"],[3,"(ii) a registered investment adviser, properly registered by or on behalf of either the Securities and Exchange Commission or any State, with respect to the investment advisory activities of such investment adviser and activities incidental to such investment advisory activities;"],[3,"(iii) an investment company that is registered under the Investment Company Act of 1940 [15 U.S.C. 80a–1 et seq.];"],[3,"(iv) an insurance company, with respect to insurance activities of the insurance company and activities incidental to such insurance activities, that is subject to supervision by a State insurance regulator; or"],[3,"(v) an entity that is subject to regulation by, or registration with, the Commodity Futures Trading Commission, with respect to activities conducted as a futures commission merchant, commodity trading adviser, commodity pool, commodity pool operator, swap execution facility, swap data repository, swap dealer, major swap participant, and activities that are incidental to such commodities and swaps activities."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/12/1844?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1844. Administration","tname":"Banks and Banking","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 3909","url":"https://www.law.cornell.edu/uscode/text/12/3909","subs":["(a)(2)"],"by":{"0":""}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"0":""}},{"t":"usc","label":"11 U.S.C. § 362","url":"https://www.law.cornell.edu/uscode/text/11/362","subs":["(a)(1)"],"stext":{"head":"§362. Automatic stay","paras":[[0,"(a) Except as provided in subsection (b) of this section, a petition filed under section 301, 302, or 303 of this title, or an application filed under section 5(a)(3) of the Securities Investor Protection Act of 1970, operates as a stay, applicable to all entities, of—"],[1,"(1) the commencement or continuation, including the issuance or employment of process, of a judicial, administrative, or other action or proceeding against the debtor that was or could have been commenced before the commencement of the case under this title, or to recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(2) the enforcement, against the debtor or against property of the estate, of a judgment obtained before the commencement of the case under this title;"],[1,"(3) any act to obtain possession of property of the estate or of property from the estate or to exercise control over property of the estate;"],[1,"(4) any act to create, perfect, or enforce any lien against property of the estate;"],[1,"(5) any act to create, perfect, or enforce against property of the debtor any lien to the extent that such lien secures a claim that arose before the commencement of the case under this title;"],[1,"(6) any act to collect, assess, or recover a claim against the debtor that arose before the commencement of the case under this title;"],[1,"(7) the setoff of any debt owing to the debtor that arose before the commencement of the case under this title against any claim against the debtor; and"],[1,"(8) the commencement or continuation of a proceeding before the United States Tax Court concerning a tax liability of a debtor that is a corporation for a taxable period the bankruptcy court may determine or concerning the tax liability of a debtor who is an individual for a taxable period ending before the date of the order for relief under this title."],[0,"(b) The filing of a petition under section 301, 302, or 303 of this title, or of an application under section 5(a)(3) of the Securities Investor Protection Act of 1970, does not operate as a stay—"],[1,"(1) under subsection (a) of this section, of the commencement or continuation of a criminal action or proceeding against the debtor;"],[1,"(2) under subsection (a)—"],[2,"(A) of the commencement or continuation of a civil action or proceeding—"],[3,"(i) for the establishment of paternity;"],[3,"(ii) for the establishment or modification of an order for domestic support obligations;"],[3,"(iii) concerning child custody or visitation;"],[3,"(iv) for the dissolution of a marriage, except to the extent that such proceeding seeks to determine the division of property that is property of the estate; or"],[3,"(v) regarding domestic violence;"],[2,"(B) of the collection of a domestic support obligation from property that is not property of the estate;"],[2,"(C) with respect to the withholding of income that is property of the estate or property of the debtor for payment of a domestic support obligation under a judicial or administrative order or a statute;"],[2,"(D) of the withholding, suspension, or restriction of a driver's license, a professional or occupational license, or a recreational license, under State law, as specified in section 466(a)(16) of the Social Security Act;"],[2,"(E) of the reporting of overdue support owed by a parent to any consumer reporting agency as specified in section 466(a)(7) of the Social Security Act;"],[2,"(F) of the interception of a tax refund, as specified in sections 464 and 466(a)(3) of the Social Security Act or under an analogous State law; or"],[2,"(G) of the enforcement of a medical obligation, as specified under title IV of the Social Security Act;"],[1,"(3) under subsection (a) of this section, of any act to perfect, or to maintain or continue the perfection of, an interest in property to the extent that the trustee's rights and powers are subject to such perfection under section 546(b) of this title or to the extent that such act is accomplished within the period provided under section 547(e)(2)(A) of this title;"],[1,"(4) under paragraph (1), (2), (3), or (6) of subsection (a) of this section, of the commencement or continuation of an action or proceeding by a governmental unit or any organization exercising authority under the Convention on the Prohibition of the Development, Production, Stockpiling and Use of Chemical Weapons and on Their Destruction, opened for signature on January 13, 1993, to enforce such governmental unit's or organization's police and regulatory power, including the enforcement of a judgment other than a money judgment, obtained in an action or proceeding by the governmental unit to enforce such governmental unit's or organization's police or regulatory power;"],[1,"[(5) Repealed. Pub. L. 105–277, div. I, title VI, §603(1), Oct. 21, 1998, 112 Stat. 2681–866;]"],[1,"(6) under subsection (a) of this section, of the exercise by a commodity broker, forward contract merchant, stockbroker, financial institution, financial participant, or securities clearing agency of any contractual right (as defined in section 555 or 556) under any security agreement or arrangement or other credit enhancement forming a part of or related to any commodity contract, forward contract or securities contract, or of any contractual right (as defined in section 555 or 556) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such contracts, including any master agreement for such contracts;"],[1,"(7) under subsection (a) of this section, of the exercise by a repo participant or financial participant of any contractual right (as defined in section 559) under any security agreement or arrangement or other credit enhancement forming a part of or related to any repurchase agreement, or of any contractual right (as defined in section 559) to offset or net out any termination value, payment amount, or other transfer obligation arising under or in connection with 1 or more such agreements, including any master agreement for such agreements;"],[1,"(8) under subsection (a) of this section, of the commencement of any action by the Secretary of Housing and Urban Development to foreclose a mortgage or deed of trust in any case in which the mortgage or deed of trust held by the Secretary is insured or was formerly insured under the National Housing Act and covers property, or combinations of property, consisting of five or more living units;"],[1,"(9) under subsection (a), of—"],[2,"(A) an audit by a governmental unit to determine tax liability;"],[2,"(B) the issuance to the debtor by a governmental unit of a notice of tax deficiency;"],[2,"(C) a demand for tax returns; or"],[2,"(D) the making of an assessment for any tax and issuance of a notice and demand for payment of such an assessment (but any tax lien that would otherwise attach to property of the estate by reason of such an assessment shall not take effect unless such tax is a debt of the debtor that will not be discharged in the case and such property or its proceeds are transferred out of the estate to, or otherwise revested in, the debtor)."],[1,"(10) under subsection (a) of this section, of any act by a lessor to the debtor under a lease of nonresidential real property that has terminated by the expiration of the stated term of the lease before the commencement of or during a case under this title to obtain possession of such property;"],[1,"(11) under subsection (a) of this section, of the presentment of a negotiable instrument and the giving of notice of and protesting dishonor of such an instrument;"],[1,"(12) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Transportation under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage, or a security interest in or relating to a vessel or vessel under construction, held by the Secretary of Transportation under chapter 537 of title 46 or section 109(h) of title 49, or under applicable State law;"],[1,"(13) under subsection (a) of this section, after the date which is 90 days after the filing of such petition, of the commencement or continuation, and conclusion to the entry of final judgment, of an action which involves a debtor subject to reorganization pursuant to chapter 11 of this title and which was brought by the Secretary of Commerce under section 31325 of title 46 (including distribution of any proceeds of sale) to foreclose a preferred ship or fleet mortgage in a vessel or a mortgage, deed of trust, or other security interest in a fishing facility held by the Secretary of Commerce under chapter 537 of title 46;"],[1,"(14) under subsection (a) of this section, of any action by an accrediting agency regarding the accreditation status of the debtor as an educational institution;"],[1,"(15) under subsection (a) of this section, of any action by a State licensing body regarding the licensure of the debtor as an educational institution;"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/11/362?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§362. Automatic stay","tname":"Bankruptcy","by":{"0":""}},{"t":"usc","label":"12 U.S.C. § 1823","url":"https://www.law.cornell.edu/uscode/text/12/1823","subs":["(c)"],"by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 157","url":"https://www.law.cornell.edu/uscode/text/28/157","subs":["(d)"],"by":{"0":""}},{"t":"usc","label":"28 U.S.C. § 2283","url":"https://www.law.cornell.edu/uscode/text/28/2283","by":{"0":""}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","subs":["(4)"],"by":{"0":""}}]};